import{at as e,it as t,n,vt as r}from"./chunks/framework.CW63qgVu.js";var i=JSON.parse(`{"title":"Conversion","description":"Convert and compress disc images in retroBITE: CHD, CSO, ZSO, ECM, VCD, RVZ, WBFS and back to ISO or BIN/CUE, with the bundled chdman, maxcso, ecm, cue2pops and nodtool.","frontmatter":{"title":"Conversion","description":"Convert and compress disc images in retroBITE: CHD, CSO, ZSO, ECM, VCD, RVZ, WBFS and back to ISO or BIN/CUE, with the bundled chdman, maxcso, ecm, cue2pops and nodtool.","order":7},"headers":[],"relativePath":"docs/guide/conversion.md","filePath":"docs/guide/conversion.md","lastUpdated":1791277802000}`),a={name:`docs/guide/conversion.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to “Conversion”">​</a></h1><p><strong>Tools → Conversion</strong> converts and compresses the disc images in your library. Compress games to save space, convert them to the format your loader or emulator expects, or unpack them back to a plain ISO or BIN/CUE.</p><p>Every conversion runs on the server, in a queue, with the tools that ship inside the web image. Nothing needs installing.</p><h2 id="formats" tabindex="-1">Formats <a class="header-anchor" href="#formats" aria-label="Permalink to “Formats”">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>What it is</th><th>Made from</th><th>Unpacks to</th><th>Consoles</th></tr></thead><tbody><tr><td><strong>CHD</strong></td><td>Compressed, lossless disc image, widely supported by emulators</td><td>BIN/CUE, IMG, ISO</td><td>BIN/CUE or ISO</td><td>PlayStation, PlayStation 2</td></tr><tr><td><strong>CSO</strong></td><td>Compressed ISO</td><td>ISO</td><td>ISO</td><td>PlayStation 2</td></tr><tr><td><strong>ZSO</strong></td><td>Compressed ISO that is faster to read, at a slightly larger size</td><td>ISO</td><td>ISO</td><td>PlayStation 2</td></tr><tr><td><strong>ECM</strong></td><td>Disc image with the error-correction data stripped, losslessly</td><td>BIN/CUE, IMG, ISO</td><td>BIN</td><td>PlayStation</td></tr><tr><td><strong>VCD</strong></td><td>POPStarter&#39;s format for running PlayStation games on a PlayStation 2</td><td>BIN/CUE</td><td>BIN/CUE</td><td>PlayStation</td></tr><tr><td><strong>RVZ</strong></td><td>Dolphin&#39;s compressed, lossless format</td><td>ISO, GCM, WIA, WBFS, CISO, GCZ</td><td>ISO</td><td>GameCube, Wii</td></tr><tr><td><strong>WBFS</strong></td><td>Scrubbed Wii image for USB Loader GX and WiiFlow</td><td>ISO, WIA, RVZ, CISO, GCZ</td><td>ISO</td><td>Wii</td></tr></tbody></table><p>Conversions are offered per console, for the formats that console&#39;s loaders and emulators read. What a file can become depends on both its console and its file type: the page only offers conversions that apply. For CHD, CD-based and DVD-based games are handled separately, so a PlayStation 2 DVD game becomes a DVD CHD and unpacks back to ISO.</p><p>More consoles get conversions as their loaders and formats are added.</p><h2 id="converting-games" tabindex="-1">Converting games <a class="header-anchor" href="#converting-games" aria-label="Permalink to “Converting games”">​</a></h2><ol><li>Open <strong>Tools → Conversion</strong> and pick a console.</li><li>Pick one game or file to see what it can become, or select several to convert them all at once. Search and the file type filter narrow the list.</li><li>Choose the <strong>output format</strong>. Only formats the selected files can be turned into are offered.</li><li>Set the options, then <strong>Add to queue</strong>. Each file is queued as a conversion of its own, with the same options.</li></ol><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Compression</strong></td><td>Trade size for speed where the format allows it. CHD offers best (lzma, zlib, flac) or fast (zlib). CSO and ZSO offer default, fast or smallest.</td></tr><tr><td><strong>Verify checksum</strong></td><td>Checks the output with the tool&#39;s own verifier before it goes into your library. Offered for CHD, RVZ, WBFS and ISO from nodtool.</td></tr><tr><td><strong>Keep source</strong></td><td>Leaves the original files where they are. Off, they are deleted, but only after the output is written and verified.</td></tr><tr><td><strong>Advanced options</strong></td><td>The tools&#39; own settings, such as CHD hunk size, CSO block size, the RVZ zstd level or POPStarter&#39;s PAL to NTSC patch. The defaults suit most games.</td></tr></tbody></table><h2 id="the-queue" tabindex="-1">The queue <a class="header-anchor" href="#the-queue" aria-label="Permalink to “The queue”">​</a></h2><p>The queue shows every conversion with its status and progress: queued, running, verifying, done, failed or cancelled. You can cancel a running conversion, retry a failed one, open its log to see the tool&#39;s output, and clear finished ones from the list.</p><p>Conversions are safe to interrupt:</p><ul><li>The tool writes into a staging folder, never straight into your library. A failed or cancelled conversion leaves nothing behind.</li><li>The finished file is moved into the console&#39;s folder without overwriting anything already there.</li><li>With <strong>Keep source</strong> off, the originals are removed only once the new file is in place.</li><li>Multi-disc games get a fresh <code>.m3u</code> playlist, and the console is scanned so the new files show up straight away.</li><li>If retroBITE restarts mid-conversion, the interrupted conversion is marked failed and its half-written output removed. Retry it from the queue.</li></ul><h2 id="bundled-tools" tabindex="-1">Bundled tools <a class="header-anchor" href="#bundled-tools" aria-label="Permalink to “Bundled tools”">​</a></h2><p>These tools ship inside the web image at pinned versions:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Used for</th></tr></thead><tbody><tr><td><strong>chdman</strong></td><td>CUE/BIN, IMG and ISO to CHD, and back</td></tr><tr><td><strong>maxcso</strong></td><td>ISO to CSO and ZSO, and back</td></tr><tr><td><strong>ecm / unecm</strong></td><td>Disc images to ECM, and ECM back to BIN</td></tr><tr><td><strong>cue2pops / pops2cue</strong></td><td>BIN/CUE to POPStarter VCD, and VCD back to BIN/CUE</td></tr><tr><td><strong>nodtool</strong></td><td>GameCube and Wii images to RVZ, WBFS and ISO</td></tr></tbody></table><p>The <strong>Tools</strong> panel on the Conversion page shows the version of each tool and whether it was found. A missing tool turns off only the formats that need it. To use a different build, set its path in <code>.env</code>. See <a href="./../getting-started/configuration#conversion">Configuration</a> for the paths, how many conversions run at once and how long one may take.</p><div class="tip custom-block"><p class="custom-block-title">Large libraries</p><p>One conversion runs at a time by default, because a second one on the same disk mostly slows both down. On fast storage, raise <code>CONVERSION_CONCURRENCY</code> and <code>QUEUE_WORKERS_CONVERSION</code> together.</p></div>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};